      });
    }

    // 调用任务调度器添加批量任务
    const taskIds = await taskScheduler.addBatchTasks(
      userId,
      type,
      inputs,
      options
    );

    // 返回成功响应
    res.json({
      success: true,
      taskIds,
      total: taskIds.length
    });
  } catch (error) {
    // 返回错误响应
    res.status(500).json({
      success: false,
      error: (error as Error).message
    });
  }
});
