    systemPrompt?: string;
    tools?: string[];
    config?: Record<string, unknown>;
}

const logger = new ScopedLogger("Manager");

/**
 * 智能体管理器
 */
export class AgentManager {
    private sessionManager: SessionManager;
    private providers: Map<string, LLMProvider>;
    private agents: Map<string, Info>;
    private config: Config;

    constructor(config: Config = {}) {
        this.config = config;
        this.sessionManager = new SessionManager(config);
        this.providers = new Map();
        this.agents = new Map();

        // 初始化默认 provider
        if (config.apiKey) {
            const { OpenAIProvider } = require('../providers/openai');
            this.providers.set('default', new OpenAIProvider({
                apiKey: config.apiKey,
                baseURL: config.baseURL,
                model: config.model
            }));
        }

        // 设置工具上下文
        ToolRegistry.setContext({
            sessionId: this.sessionManager.id,
            sessionPath: this.sessionManager.sessionPath,
        });
    }

    /**
     * 注册 Provider
     */
    registerProvider(name: string, provider: LLMProvider): void {
        this.providers.set(name, provider);
    }

    /**
     * 获取 Provider
     */
    getProvider(name: string = 'default'): LLMProvider | undefined {
        return this.providers.get(name);
    }

    /**
     * 添加工具
     */
    addTool(tool: BaseTool): void {
        ToolRegistry.register(tool);
    }

    /**
     * 加载智能体配置
     */
    async loadAgent(name: string): Promise<Info | null> {
        // 如果已经加载过，直接返回
        if (this.agents.has(name)) {
            return this.agents.get(name)!;
        }

        const agentDir = this.config.agentDir || path.join(process.cwd(), 'agents');
        const agentFile = path.join(agentDir, `${name}.json`);

        try {
            const content = await fs.readFile(agentFile, 'utf-8');
            const config = JSON.parse(content) as Info;
            this.agents.set(name, config);
            return config;
        } catch (error) {
            logger.error(`Failed to load agent ${name}:`, error);
            return null;
        }
    }

    /**
     * 保存智能体配置
     */
    async saveAgent(name: string, config: Info): Promise<void> {
        const agentDir = this.config.agentDir || path.join(process.cwd(), 'agents');

        // 确保 agents 目录存在
        try {
            await fs.mkdir(agentDir, { recursive: true });
        } catch {
            // 目录已存在，忽略
        }

        const agentFile = path.join(agentDir, `${name}.json`);
        await fs.writeFile(agentFile, JSON.stringify(config, null, 2));

        this.agents.set(name, config);
        logger.info(`Agent ${name} saved to ${agentFile}`);
    }

    /**
     * 获取智能体
     */
    async get(name: string): Promise<Info | null> {
        return this.loadAgent(name);
    }

    /**
     * 列出所有智能体
     */
    async list(): Promise<Info[]> {
        const agentDir = this.config.agentDir || path.join(process.cwd(), 'agents');

        try {
            const files = await fs.readdir(agentDir);
            const agents: Info[] = [];

            for (const file of files) {
                if (file.endsWith('.json')) {
                    const name = file.replace('.json', '');
                    const agent = await this.loadAgent(name);
                    if (agent) {
                        agents.push(agent);
                    }
                }
            }

            return agents;
        } catch (error) {
            logger.warn('Failed to list agents:', error);
            return [];
        }
    }

    /**
     * 获取默认智能体
     */
    async defaultAgent(): Promise<string> {
        return 'default';
    }

    /**
     * AI 生成新智能体
     */
    async generate(input: {
        description: string;
        model?: {
            name?: string;
            temperature?: number;
        };
    }): Promise<Info | null> {
        const provider = this.getProvider();
        if (!provider) {
            logger.error('No provider available for generating agent');
            return null;
        }

        const messages: Message[] = [
            {
                role: 'system',
                content: 'You are an expert AI agent designer. Create a well-structured agent configuration based on the user description.'
            },
            {
                role: 'user',
                content: `Create an AI agent with the following description:\n${input.description}\n\nReturn the configuration as a JSON object with fields: name, description, systemPrompt, tools (array of tool names), and config (any additional configuration).`
            }
        ];

        try {
            const response = await provider.generate(messages, {
                model: input.model?.name,
                temperature: input.model?.temperature || 0.7,
            });

            // 尝试解析响应中的 JSON
            const jsonMatch = response?.content.match(/\{[\s\S]*\}/);
            if (jsonMatch) {
                return JSON.parse(jsonMatch[0]) as Info;
            }

            return null;
        } catch (error) {
            logger.error('Failed to generate agent:', error);
            return null;
        }
    }
}
